class InputContractError(RuntimeError):
    """Raised when any summariser input violates the pre-registered contract."""


@dataclass(frozen=True)
class InputPaths:
    config: Path = CONFIG
    manifest: Path = MANIFEST
    dense: Path = DENSE_JSONL
    control: Path = CONTROL_JSONL
    oracle: Path = ORACLE_JSONL


DEFAULT_PATHS = InputPaths()


def _load_jsonl(path: Path, label: str) -> list[dict[str, Any]]:
    if not path.is_file():
        raise InputContractError(f"missing required input {label!r}: {path}")
    rows: list[dict[str, Any]] = []
    for line_number, line in enumerate(
        path.read_text(encoding="utf-8").splitlines(), 1
    ):
        if not line.strip():
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError as exc:
            raise InputContractError(
                f"{label} line {line_number} is not valid JSON: {exc}"
            ) from exc
        if not isinstance(row, dict):
            raise InputContractError(f"{label} line {line_number} is not an object")
        rows.append(row)
    return rows


def _index_unique(
    rows: Sequence[Mapping[str, Any]], label: str
) -> dict[str, Mapping[str, Any]]:
    index: dict[str, Mapping[str, Any]] = {}
    for row in rows:
        if "sample_id" not in row:
            raise InputContractError(f"{label} record is missing sample_id")
        sample_id = str(row["sample_id"])
        if sample_id in index:
            raise InputContractError(f"{label} has duplicate sample_id {sample_id!r}")
        index[sample_id] = row
    return index


def _verify_pins(config: Mapping[str, Any], root: Path) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    for section in ("inputs_sha256", "summarizer_inputs"):
        specs = config.get(section, {})
        if not isinstance(specs, Mapping):
            raise InputContractError(f"config {section} must be an object")
        for name, spec in specs.items():
            if not isinstance(spec, Mapping):
                raise InputContractError(f"config pin {section}.{name} must be an object")
            expected = spec.get("sha256")
            relative = spec.get("path")
            if expected is None:
                continue
            if relative is None:
                raise InputContractError(f"config pin {section}.{name} has no path")
            path = Path(str(relative))
            if not path.is_absolute():
                path = root / path
            if not path.is_file():
                raise InputContractError(
                    f"pinned file {path} is missing (fail closed)"
                )
            actual = file_sha256(path)
            if actual != str(expected):
                raise InputContractError(
                    f"pin {section}.{name} sha256 mismatch: expected {expected}, "
                    f"got {actual} (fail closed)"
                )
            checks.append(
                {
                    "name": f"{section}.{name}",
                    "path": str(path),
                    "sha256": actual,
                    "matches": True,
                }
            )
    return {"pins_verified": True, "checks": checks}


def _validate_oracle_record(
    sample_id: str,
    record: Mapping[str, Any],
    *,
    manifest_sha256: str,
    config_sha256: str,
) -> dict[str, Any]:
    if str(record.get("arm")) != ARM_ORACLE:
        raise InputContractError(
            f"oracle sample {sample_id!r} arm={record.get('arm')!r} != {ARM_ORACLE!r}"
        )
    for field, expected in (
        ("manifest_sha256", manifest_sha256),
        ("config_sha256", config_sha256),
    ):
        if str(record.get(field)) != str(expected):
            raise InputContractError(
                f"oracle sample {sample_id!r} {field} mismatch (fail closed)"
            )
    if str(record.get("record_sha256")) != record_sha256(record):
        raise InputContractError(
            f"oracle sample {sample_id!r} record_sha256 mismatch (fail closed)"
        )
    for field, expected in (
        ("requested_budget", BUDGET),
        ("region_grid", REGION_GRID_FIXED),
        ("local_candidate_cap", LOCAL_CANDIDATE_CAP),
        ("output_group_count", BUDGET),
        ("real_group_count", EXPECTED_REAL),
        ("context_group_count", EXPECTED_CONTEXT),
    ):
        try:
            actual = int(record.get(field))
        except (TypeError, ValueError) as exc:
            raise InputContractError(
                f"oracle sample {sample_id!r} {field}={record.get(field)!r} is not "
                f"an integer (fail closed)"
            ) from exc
        if actual != int(expected):
            raise InputContractError(
                f"oracle sample {sample_id!r} {field}={actual} != {expected} "
                f"(fail closed)"
            )
    if bool(record.get("identity_bypass")):
        raise InputContractError(
            f"oracle sample {sample_id!r} is an identity bypass (fail closed)"
        )
    grid = [int(value) for value in record.get("image_grid_thw", [])]
    if len(grid) != 3 or grid[0] != 1 or grid[1] * grid[2] != int(
        record.get("full_patch_tokens", -1)
    ):
        raise InputContractError(
            f"oracle sample {sample_id!r} image_grid_thw {grid} is inconsistent"
        )
    full_groups = int(record.get("full_llm_visual_tokens", -1))
    if full_groups <= BUDGET:
        raise InputContractError(
            f"oracle sample {sample_id!r} G={full_groups} <= {BUDGET} (fail closed)"
        )
    selected = [int(value) for value in record.get("selected_group_indices", [])]
    if len(selected) != BUDGET:
        raise InputContractError(
            f"oracle sample {sample_id!r} selected {len(selected)} groups != {BUDGET}"
        )
    if any(later <= earlier for earlier, later in zip(selected, selected[1:])):
        raise InputContractError(
            f"oracle sample {sample_id!r} selected_group_indices not strictly ascending"
        )
    if sorted(selected) != selected or len(set(selected)) != len(selected):
        raise InputContractError(
            f"oracle sample {sample_id!r} selected_group_indices not unique"
        )
    label = record.get("label_tokenization") or {}
    if not bool(label.get("contract_ok")):
        raise InputContractError(
            f"oracle sample {sample_id!r} label branch contract not ok (fail closed)"
        )
    margin = record.get("margin") or {}
    margin_value = margin.get("value")
    if margin_value is None or not np.isfinite(float(margin_value)):
        raise InputContractError(
            f"oracle sample {sample_id!r} margin is not finite (fail closed)"
        )
    if not bool(record.get("model_parameter_grads_all_none")):
        raise InputContractError(
            f"oracle sample {sample_id!r} has non-None parameter grads (fail closed)"
        )
    values = np.asarray(record.get("saliency_group_values", []), dtype=np.float64).reshape(-1)
    if values.size != full_groups:
        raise InputContractError(
            f"oracle sample {sample_id!r} saliency size {values.size} != G {full_groups}"
        )
    if str(record.get("saliency_sha256")) != array_sha256(values):
        raise InputContractError(
            f"oracle sample {sample_id!r} saliency_sha256 mismatch (fail closed)"
        )
    layout = record.get("layout") or {}
    if not bool(layout.get("passed")):
        raise InputContractError(
            f"oracle sample {sample_id!r} layout contract did not pass (fail closed)"
        )
    return {
        "layout_ok": True,
        "full_llm_visual_tokens": full_groups,
        "selected_group_indices": selected,
        "saliency_values": values,
        "margin_value": float(margin_value),
    }


def analyze(
    *,
    manifest_rows: Sequence[Mapping[str, Any]],
    dense_rows: Sequence[Mapping[str, Any]],
    control_rows: Sequence[Mapping[str, Any]],
    oracle_rows: Sequence[Mapping[str, Any]],
    manifest_sha256: str,
    config_sha256: str,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate the three sources and compute the pre-registered pilot result."""

    manifest_index = _index_unique(manifest_rows, "pilot_manifest")
    dense_index = _index_unique(dense_rows, "dense")
    control_index = _index_unique(control_rows, "control")
    oracle_index = _index_unique(oracle_rows, "oracle")
    if len(manifest_index) != PILOT_SAMPLE_COUNT:
        raise InputContractError(
            f"pilot manifest must hold {PILOT_SAMPLE_COUNT} unique samples, got "
            f"{len(manifest_index)}"
        )
    expected_ids = set(manifest_index)
    for label, index in (
        ("dense", dense_index),
        ("control", control_index),
        ("oracle", oracle_index),
    ):
        if set(index) != expected_ids:
            missing = sorted(expected_ids - set(index))
            extra = sorted(set(index) - expected_ids)
            raise InputContractError(
                f"{label} sample_id set != pilot manifest: missing={missing[:5]} "
                f"extra={extra[:5]} (fail closed)"
            )

    oracle_checks: dict[str, Any] = {}
    for sample_id in sorted(expected_ids, key=lambda value: (len(value), value)):
        oracle_checks[sample_id] = _validate_oracle_record(
            sample_id,
            oracle_index[sample_id],
            manifest_sha256=manifest_sha256,
            config_sha256=config_sha256,
        )

    rows: list[dict[str, Any]] = []
    per_sample: list[dict[str, Any]] = []
    for sample_id, meta in manifest_index.items():
        choices = [str(choice) for choice in meta.get("choices", [])]
        truth = answer_letter(str(meta["answer"]))
        row: dict[str, Any] = {
            "sample_id": sample_id,
            "task": str(meta["task"]),
            "source": str(meta["source"]),
            "source_dataset": str(meta["source_dataset"]),
            "ground_truth": truth,
        }
        sample_row: dict[str, Any] = {
            "sample_id": sample_id,
            "task": str(meta["task"]),
            "source": str(meta["source"]),
            "source_dataset": str(meta["source_dataset"]),
            "ground_truth": truth,
        }
        for arm, index in (
            ("dense", dense_index),
            ("control", control_index),
            ("oracle", oracle_index),
        ):
            parsed = parse_choice(str(index[sample_id].get("output_text", "")), choices)
            correct = parsed is not None and parsed == truth
            row[f"{arm}_answer"] = parsed
            row[f"{arm}_correct"] = bool(correct)
            sample_row[f"{arm}_answer"] = parsed
            sample_row[f"{arm}_correct"] = bool(correct)
            sample_row[f"{arm}_output_text"] = str(
                index[sample_id].get("output_text", "")
            )
        oracle_selected = oracle_checks[sample_id]["selected_group_indices"]
        control_selected = [
            int(value) for value in control_index[sample_id].get("selected_group_indices", [])
        ]
        dense_selected = [
            int(value) for value in dense_index[sample_id].get("selected_group_indices", [])
        ]
        overlap_control = selection_overlap(oracle_selected, control_selected)
        sample_row["saliency_retained_mass"] = retained_mass(
            oracle_checks[sample_id]["saliency_values"], oracle_selected
        )
        sample_row["oracle_control_overlap"] = overlap_control["intersection"]
        sample_row["oracle_control_jaccard"] = overlap_control["jaccard"]
        sample_row["oracle_control_exact_match"] = overlap_control["exact_match"]
        sample_row["control_selected_count"] = len(control_selected)
        sample_row["dense_selected_count"] = len(dense_selected)
        sample_row["oracle_margin"] = oracle_checks[sample_id]["margin_value"]
        rows.append(row)
        per_sample.append(sample_row)

    metrics: dict[str, Any] = {}
    for arm in ARM_ORDER:
        official = score(rows, f"{arm}_correct")
        parse_count = sum(1 for row in rows if row[f"{arm}_answer"] is not None)
        metrics[arm] = {
            "cv_bench_accuracy": official["cv_bench_accuracy"],
            "unweighted_accuracy": official["accuracy"],
            "parse_success_rate": official["parse_success_rate"],
            "parse_count": parse_count,
            "parse_denominator": PILOT_SAMPLE_COUNT,
            "source_accuracy": official["source_accuracy"],
            "sample_count": official["sample_count"],
        }

    control_correct = {row["sample_id"]: row["control_correct"] for row in rows}
    oracle_correct = {row["sample_id"]: row["oracle_correct"] for row in rows}
    w_to_r = sum(1 for sid in control_correct if not control_correct[sid] and oracle_correct[sid])
    r_to_w = sum(1 for sid in control_correct if control_correct[sid] and not oracle_correct[sid])
    unchanged_correct = sum(
        1 for sid in control_correct if control_correct[sid] and oracle_correct[sid]
    )
    unchanged_wrong = sum(
        1 for sid in control_correct if not control_correct[sid] and not oracle_correct[sid]
    )
    net = w_to_r - r_to_w

    jaccards = [row["oracle_control_jaccard"] for row in per_sample]
    retained = [row["saliency_retained_mass"] for row in per_sample]
    diagnostics = {
        "oracle_control_overlap": {
            "mean_intersection": float(
                np.mean([row["oracle_control_overlap"] for row in per_sample])
            ),
            "mean_jaccard": float(np.mean(jaccards)),
            "min_jaccard": float(np.min(jaccards)),
            "exact_match_count": int(
                sum(1 for row in per_sample if row["oracle_control_exact_match"])
            ),
            "definition": "|oracle∩control| / |oracle∪control| per sample, diagnostic only",
        },
        "saliency_retained_mass": {
            "mean": float(np.mean(retained)),
            "min": float(np.min(retained)),
            "max": float(np.max(retained)),
            "definition": (
                "sum(saliency[selected 96 groups]) / sum(saliency over all G groups); "
                "diagnostic only"
            ),
        },
    }

    comparisons = {
        "dense_minus_oracle": float(
            metrics["dense"]["cv_bench_accuracy"]
            - metrics["oracle"]["cv_bench_accuracy"]
        ),
        "dense_minus_control": float(
            metrics["dense"]["cv_bench_accuracy"]
            - metrics["control"]["cv_bench_accuracy"]
        ),
        "oracle_minus_control": float(
            metrics["oracle"]["cv_bench_accuracy"]
            - metrics["control"]["cv_bench_accuracy"]
        ),
        "oracle_minus_dense": float(
            metrics["oracle"]["cv_bench_accuracy"]
            - metrics["dense"]["cv_bench_accuracy"]
        ),
    }

    gate = {
        "pilot_sample_count": PILOT_SAMPLE_COUNT,
        "oracle_minus_control_net": net,
        "oracle_minus_control_net_min": GATE_ORACLE_MINUS_CONTROL_NET_MIN,
        "w_to_r": w_to_r,
        "w_to_r_min": GATE_W_TO_R_MIN,
        "r_to_w": r_to_w,
        "r_to_w_max": GATE_R_TO_W_MAX,
        "unchanged_correct": unchanged_correct,
        "unchanged_wrong": unchanged_wrong,
        "oracle_parse_count": metrics["oracle"]["parse_count"],
        "oracle_parse_min": GATE_ORACLE_PARSE_MIN,
        "all_24_exact_k96_layout_contracts_pass": True,
        "uses_confidence_interval": False,
        "checks": {
            "net_ge_min": net >= GATE_ORACLE_MINUS_CONTROL_NET_MIN,
            "w_to_r_ge_min": w_to_r >= GATE_W_TO_R_MIN,
            "r_to_w_le_max": r_to_w <= GATE_R_TO_W_MAX,
            "oracle_parse_ge_min": metrics["oracle"]["parse_count"] >= GATE_ORACLE_PARSE_MIN,
            "layout_contracts_all_pass": True,
        },
    }
    gate["status"] = STATUS_GO if all(gate["checks"].values()) else STATUS_STOP

    return {
        "sample_count": PILOT_SAMPLE_COUNT,
        "rows": rows,
        "per_sample": per_sample,
        "metrics": metrics,
        "comparisons": comparisons,
        "diagnostics": diagnostics,
        "gate": gate,
        "manifest_sha256": manifest_sha256,
        "config_sha256": config_sha256,
        "source_counts": {
            source: sum(1 for row in rows if row["source_dataset"] == source)
            for source in sorted({row["source_dataset"] for row in rows})
        },
    }


def build_report(
    paths: InputPaths = DEFAULT_PATHS,
    *,
    root: Path = ROOT,
) -> dict[str, Any]:
    config_path = paths.config if paths.config.is_absolute() else root / paths.config
    if not config_path.is_file():
        raise InputContractError(f"missing pre-registered config {config_path}")
    config = json.loads(config_path.read_text(encoding="utf-8"))
    config_sha256 = file_sha256(config_path)
    pins = _verify_pins(config, root)
    for path in (paths.manifest, paths.dense, paths.control, paths.oracle):
        if not path.is_file():
            raise InputContractError(f"missing required input {path} (fail closed)")

    manifest_rows = _load_jsonl(paths.manifest, "pilot_manifest")
    dense_rows = _load_jsonl(paths.dense, "dense")
    control_rows = _load_jsonl(paths.control, "control")
    oracle_rows = _load_jsonl(paths.oracle, "oracle")
    manifest_sha256 = file_sha256(paths.manifest)
    pinned_manifest = config.get("manifest", {}).get("sha256")
    if pinned_manifest is not None and str(pinned_manifest) != manifest_sha256:
        raise InputContractError(
            f"pilot manifest sha256 {manifest_sha256} != config pin {pinned_manifest}"
        )

    result = analyze(
        manifest_rows=manifest_rows,
        dense_rows=dense_rows,
        control_rows=control_rows,
        oracle_rows=oracle_rows,
        manifest_sha256=manifest_sha256,
        config_sha256=config_sha256,
        config=config,
    )
    result["status"] = result["gate"]["status"]
    result["date"] = "2026-10-05"
    result["design"] = config.get("design")
    result["is_label_aware_oracle"] = True
    result["ground_truth_answer_leakage"] = True
    result["deployable_selector"] = False
    result["is_paper_accuracy_claim"] = False
    result["accuracy_improvement_confirmed"] = False
    result["uses_confidence_interval"] = False
    result["pins"] = pins
    result["inputs_sha256"] = {
        "config": {"path": str(config_path), "sha256": config_sha256},
        "manifest": {"path": str(paths.manifest), "sha256": manifest_sha256},
        "dense": {"path": str(paths.dense), "sha256": file_sha256(paths.dense)},
        "control": {"path": str(paths.control), "sha256": file_sha256(paths.control)},
        "oracle": {"path": str(paths.oracle), "sha256": file_sha256(paths.oracle)},
    }
    result["required_statements"] = {
        "label_aware_oracle": (
            "这是 label-aware oracle 上界（ground-truth answer leakage），不是可部署 selector。"
        ),
        "not_paper_accuracy": (
            "24 样本只是泄漏 oracle 筛选，不是论文精度，不使用置信区间或"
            "『精度提升已确认』措辞。"
        ),
        "diagnostics_only": (
            "选择重叠/Jaccard 与 saliency retained mass 仅诊断，不参与 GO/STOP 门。"
        ),
    }
    result["forbidden_claims"] = list(config.get("forbidden_claims", []))
    result["generated_at"] = datetime.now(timezone.utc).astimezone().isoformat()
    return result


def render_markdown(report: Mapping[str, Any]) -> str:
    metrics = report["metrics"]
    gate = report["gate"]
    diagnostics = report["diagnostics"]
    lines = [
        "# B1 answer-margin oracle K96 pilot 汇总（label-aware oracle 筛选）",
        "",
        f"- 日期：{report['date']}",
        f"- 状态：**{report['status']}**",
        f"- 设计：`{report['design']}`",
        f"- 样本数：{report['sample_count']}（三臂绝对正确率，无置信区间）",
        "",
        "## 1. 口径",
        "",
        "- **label-aware oracle（ground-truth answer leakage）**：oracle 用官方正确答案",
        "  分叉 token 计算 saliency，只是可证伪上界，**不可部署**。",
        "- 24 样本**不是论文精度**；本报告不计算 CI、不使用『精度提升已确认』措辞。",
        "- 选择重叠/Jaccard 与 saliency retained mass **仅诊断**，不参与 GO/STOP 门。",
        "",
        "## 2. 三臂绝对正确率（官方 `cv_bench_accuracy`）",
        "",
        "| 臂 | cv_bench_accuracy | unweighted | parse | parse count |",
        "| --- | --- | --- | --- | --- |",
    ]
    for arm in ARM_ORDER:
        item = metrics[arm]
        lines.append(
            f"| {arm} | {item['cv_bench_accuracy']:.6f} | "
            f"{item['unweighted_accuracy']:.6f} | {item['parse_success_rate']:.6f} | "
            f"{item['parse_count']}/{item['parse_denominator']} |"
        )
    lines += [
        "",
        "## 3. headroom 与 oracle−control 迁移",
        "",
        f"- dense − oracle：`{report['comparisons']['dense_minus_oracle']:.6f}`",
        f"- dense − control：`{report['comparisons']['dense_minus_control']:.6f}`",
        f"- oracle − control（绝对）：`{report['comparisons']['oracle_minus_control']:.6f}`",
        f"- W→R：`{gate['w_to_r']}`，R→W：`{gate['r_to_w']}`，net：`{gate['oracle_minus_control_net']}`",
        f"- 不变对（都对/都错）：`{gate['unchanged_correct']}` / `{gate['unchanged_wrong']}`",
        "",
        "## 4. 诊断量（不作为门）",
        "",
        f"- oracle∩control 平均交集："
        f"`{diagnostics['oracle_control_overlap']['mean_intersection']:.3f}`，"
        f"平均 Jaccard：`{diagnostics['oracle_control_overlap']['mean_jaccard']:.6f}`，"
        f"精确相同样本数：`{diagnostics['oracle_control_overlap']['exact_match_count']}`。",
        f"- saliency retained mass 均值："
        f"`{diagnostics['saliency_retained_mass']['mean']:.6f}`。",
        "",
        "## 5. 预注册 GO/STOP 门",
        "",
        "| 条件 | 要求 | 实际 | 通过 |",
        "| --- | --- | --- | --- |",
        f"| oracle−control net | ≥ {gate['oracle_minus_control_net_min']} | "
        f"{gate['oracle_minus_control_net']} | {'✅' if gate['checks']['net_ge_min'] else '❌'} |",
        f"| W→R | ≥ {gate['w_to_r_min']} | {gate['w_to_r']} | "
        f"{'✅' if gate['checks']['w_to_r_ge_min'] else '❌'} |",
        f"| R→W | ≤ {gate['r_to_w_max']} | {gate['r_to_w']} | "
        f"{'✅' if gate['checks']['r_to_w_le_max'] else '❌'} |",
        f"| oracle parse | ≥ {gate['oracle_parse_min']}/{report['sample_count']} | "
        f"{gate['oracle_parse_count']} | "
        f"{'✅' if gate['checks']['oracle_parse_ge_min'] else '❌'} |",
        f"| 精确 K96 布局 | 24/24 | 24/24 | ✅ |",
        "",
        f"- 结论：**{gate['status']}**（满足全部门才 GO）。",
        "- 该门只是 24 样本泄漏 oracle 的筛选决策，**不是精度或部署结论**。",
        "",
        "## 6. 输入 SHA256",
        "",
    ]
    for name, spec in report["inputs_sha256"].items():
        lines.append(f"- `{name}`: `{spec['path']}` → `{spec['sha256']}`")
    lines += [
        "",
        "## 7. 逐样本（诊断）",
        "",
        "| sample_id | task | source | truth | control | oracle | 迁移 | retained mass | Jaccard |",
        "| --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for row in report["per_sample"]:
        transition = (
            "W→R"
            if (not row["control_correct"] and row["oracle_correct"])
            else "R→W"
            if (row["control_correct"] and not row["oracle_correct"])
            else "same"
        )
        lines.append(
            f"| {row['sample_id']} | {row['task']} | {row['source_dataset']} | "
            f"{row['ground_truth']} | {row['control_answer']} | {row['oracle_answer']} | "
            f"{transition} | {row['saliency_retained_mass']:.4f} | "
            f"{row['oracle_control_jaccard']:.4f} |"
        )
    lines += [
        "",
        "禁止据此报告声称：" + "、".join(report["forbidden_claims"]) + "。",
        "",
    ]
    return "\n".join(lines)


def _csv_rows(per_sample: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    fields = (
        "sample_id",
        "task",
        "source",
        "source_dataset",
        "ground_truth",
        "dense_answer",
        "dense_correct",
        "control_answer",
        "control_correct",
        "oracle_answer",
        "oracle_correct",
        "oracle_margin",
        "saliency_retained_mass",
        "oracle_control_overlap",
        "oracle_control_jaccard",
        "oracle_control_exact_match",
        "control_selected_count",
        "dense_selected_count",
    )
    return [{field: row.get(field) for field in fields} for row in per_sample]


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=CONFIG)
    parser.add_argument("--manifest", type=Path, default=MANIFEST)
    parser.add_argument("--dense", type=Path, default=DENSE_JSONL)
    parser.add_argument("--control", type=Path, default=CONTROL_JSONL)
    parser.add_argument("--oracle", type=Path, default=ORACLE_JSONL)
    parser.add_argument("--report-dir", type=Path, default=REPORT_DIR)
    parser.add_argument("--no-write", action="store_true")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    paths = InputPaths(
        config=args.config,
        manifest=args.manifest,
        dense=args.dense,
        control=args.control,
        oracle=args.oracle,
    )
    try:
        report = build_report(paths)
    except (InputContractError, OSError) as error:
        print(f"FAIL_CLOSED: {error}", file=sys.stderr)
        return 2

    if not args.no_write:
        report_dir = args.report_dir
        report_dir.mkdir(parents=True, exist_ok=True)
        (report_dir / REPORT_JSON.name).write_text(
            json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        (report_dir / REPORT_MD.name).write_text(
            render_markdown(report), encoding="utf-8"
        )
        with (report_dir / REPORT_CSV.name).open("w", encoding="utf-8", newline="") as stream:
            writer = csv.DictWriter(stream, fieldnames=list(_csv_rows(report["per_sample"])[0]))
            writer.writeheader()
            writer.writerows(_csv_rows(report["per_sample"]))

    print(
        json.dumps(
            {
                "status": report["status"],
                "oracle_minus_control_net": report["gate"]["oracle_minus_control_net"],
                "w_to_r": report["gate"]["w_to_r"],
                "r_to_w": report["gate"]["r_to_w"],
                "oracle_parse_count": report["gate"]["oracle_parse_count"],
                "oracle_cv_bench_accuracy": report["metrics"]["oracle"][
                    "cv_bench_accuracy"
                ],
                "control_cv_bench_accuracy": report["metrics"]["control"][
                    "cv_bench_accuracy"
                ],
                "dense_cv_bench_accuracy": report["metrics"]["dense"][
                    "cv_bench_accuracy"
                ],
            },
            ensure_ascii=False,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
